contract InvMutTest {
  C c;
  constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
  function freezeMustStick(address t, bool f) public {
    c.freezeAccount(t, f); if (__ESBMC_reverted()) return;
    assert(c.frozenAccount(t) == f);
  }
  receive() external payable {}
  fallback() external payable {}
}

