pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _freezeMustStick(address t, bool f) internal {
        try c.freezeAccount(t, f) {} catch { return; }
        assertTrue(c.frozenAccount(t) == f);
    }

    function testFuzz_freezeMustStick(address t, bool f) public {
        vm.assume(t.code.length == 0 && uint160(t) > 0xffff && t != address(this) && t != address(c) && t != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && t != 0x000000000000000000636F6e736F6c652e6c6f67 && t != 0x4e59b44847b379578588920cA78FbF26c0B4956C && t != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _freezeMustStick(t, f);
    }

    receive() external payable {}

    fallback() external payable {}
}
